#!/usr/bin/env bash
# probe_D449.sh — проба пункта D449: `hooks/five-whys-gate.sh` судит вызов СУБАГЕНТА по
#                 расшифровке и поводам РОДИТЕЛЯ, потому что признак субагента брался из
#                 имени файла (`agent-*` в basename `transcript_path`), а харнесс кладёт
#                 туда путь родителя ВСЕГДА. Признак субагента живёт в поле `agent_id`.
# Результат: payload с `agent_id` не получает отказа по стоячему поводу родителя; тот же
#            payload без поля отказ получает; цепочка причин из расшифровки РОДИТЕЛЯ
#            субагенту не зачитывается.
# Проверка результата: bash hooks/tests/fixtures/probe_D449.sh даёт 0
#
# Коды: 0 — желаемое поведение соблюдено; 1 — дефект наблюдён; 2 — рамка не собралась.
#
# Замер 17 сентября 2026 (зонд в настройках проекта, 32 записи payload): у вызова
# инструмента `transcript_path` всегда родительский, `agent_id` и `agent_type` есть только
# у субагента (24 записи из 32), поля с расшифровкой агента на этих событиях нет вовсе.
# Механизм зовётся НА МЕСТЕ, из своего каталога: гейт резолвит библиотеки по `BASH_SOURCE`,
# и копия в песочницу оставила бы его без них. Состояние уводится в песочницу через
# STATE_DIR, живое состояние не читается и не пишется.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/../../.." && pwd -P)"
MECH="${CLAUDSOUL_REPO:-$ROOT}"
HOOK="$MECH/hooks/five-whys-gate.sh"
[ -f "$HOOK" ] || { echo "probe_D449: нет $HOOK" >&2; exit 2; }
command -v jq >/dev/null 2>&1 || { echo "probe_D449: нет jq" >&2; exit 2; }
T=$(cd "$(mktemp -d)" && pwd -P) || { echo "probe_D449: нет временного каталога" >&2; exit 2; }
trap 'rm -rf "$T"' EXIT
S="$T/state"; mkdir -p "$S"

mk_plain() {  # расшифровка без цепочки причин
    : > "$1"
    printf '{"type":"user","message":{"role":"user","content":[{"type":"text","text":"чини"}]}}\n' >> "$1"
    jq -cn '{type:"assistant",message:{role:"assistant",content:[{type:"text",text:"Правлю строку, сейчас будет зелено."}]}}' >> "$1"
}
mk_chain() {  # расшифровка, где цепочка причин произнесена
    : > "$1"
    printf '{"type":"user","message":{"role":"user","content":[{"type":"text","text":"чини"}]}}\n' >> "$1"
    # Форма цепочки — та же, что у свидетеля `test_gate_deny_per_kind.sh:120`: три «почему»
    # со стрелками и названный корень. Двух «почему» гейту мало (`FIVE_WHYS_MIN`), и первая
    # редакция пробы краснела на СВОЁМ контроле, а не на дефекте.
    jq -cn '{type:"assistant",message:{role:"assistant",content:[{type:"text",text:"Почему упало? → hooks/x.sh:12 читает пустой файл. Почему файл пуст? → писатель молчит при отказе. Почему молчит? → код возврата глотается. Корень назван."}]}}' >> "$1"
}
call() {  # call <sid> <расшифровка> [agent_id]
    jq -cn --arg s "$1" --arg p "$2" --arg a "${3:-}" \
        '{session_id:$s, tool_name:"Write", transcript_path:$p, tool_input:{file_path:"/repo/x.sh"}}
         + (if $a == "" then {} else {agent_id:$a, agent_type:"general-purpose"} end)' \
      | STATE_DIR="$S" bash "$HOOK" 2>/dev/null
}
denied() { grep -q '"permissionDecision":"deny"' <<< "${1:-}"; }

TR="$T/parent.jsonl"; mk_plain "$TR"

# Положительный контроль: тот же повод у РОДИТЕЛЯ обязан давать отказ. Без него «отказа нет»
# неотличимо от «гейт онемел совсем» — и проба зеленела бы на выпотрошенном механизме.
printf '2' > "$S/error_streak_fired_ctl"
OUT=$(call ctl "$TR")
denied "$OUT" || { echo "probe_D449: контроль — родитель не получил отказа, судить нечем: ${OUT:0:160}" >&2; exit 2; }

# Суд 1: то же самое, но вызов принадлежит субагенту. Поле есть — отказа быть не должно.
# Повод кладётся В ФАЙЛ СУБАГЕНТА (D452, 18 сентября 2026): с тех пор как поводы ключуются
# актором, повод родителя субагенту не виден вовсе, и проба зеленела бы оттого, что судить
# стало нечего, — а предмет суда здесь иной: право на отказ снято при ЖИВОМ своём поводе.
printf '2' > "$S/error_streak_fired_sub.agent-a1b2c3"
OUT=$(call sub "$TR" a1b2c3)
if denied "$OUT"; then
    echo "probe_D449: дефект — субагент получил отказ по стоячему поводу родителя" >&2
    exit 1
fi

# Суд 2: текст хода берётся у АКТОРА. У родителя цепочка произнесена, у субагента в его
# собственной расшифровке — нет; гейт, читающий актора, обязан НАПОМНИТЬ, а читающий
# родителя промолчит, зачтя чужую работу. След выбран тот, который у субагента ЕСТЬ:
# первая редакция судила по строке `chain-ok|`, а её запись субагенту подавлена отдельным
# условием при любом резолвере — проба была слепа (находка скептика 18 сентября 2026).
SID=actor
# Повод кладётся в ОБА имени — общее и с суффиксом актора. Предмет суда здесь один: «чью
# расшифровку гейт читает». Если повод положить только под именем актора, то на дереве ДО
# D452 прежний читатель его не увидит, гейт промолчит по отсутствию повода — и проба
# покраснеет с ВЕРНЫМ кодом, но НЕВЕРНЫМ диагнозом, смешав два предмета (находка
# адверсариальной проверки 18 сентября 2026). Оба имени делают повод живым на любом дереве.
printf '2' > "$S/error_streak_fired_${SID}.agent-deadbeef"
printf '2' > "$S/error_streak_fired_${SID}"
PAR="$T/parent-chain.jsonl"; mk_chain "$PAR"
mkdir -p "$T/$SID/subagents"
mk_plain "$T/$SID/subagents/agent-deadbeef.jsonl"
# След суда — журнал стража, а не вывод (D1151, 31 октября 2026): запись субагента молчит при любом поводе, а строку
# `turn:…|actor:<суффикс>|<виды>` страж пишет только тогда, когда цепочки у актора НЕ нашёл, — до выбора вывода.
noticed() { grep -qF "|actor:.agent-$2|" "$S/five-whys-$1.seen" 2>/dev/null; }
call "$SID" "$PAR" deadbeef >/dev/null
if ! noticed "$SID" deadbeef; then
    echo "probe_D449: дефект — гейт промолчал субагенту, зачтя цепочку из расшифровки РОДИТЕЛЯ" >&2
    exit 1
fi
# Контроль к нему: цепочка в СОБСТВЕННОЙ расшифровке субагента обязана зачитываться.
SID=actor_ok
printf '2' > "$S/error_streak_fired_${SID}.agent-cafe"
printf '2' > "$S/error_streak_fired_${SID}"
PAR2="$T/parent-plain.jsonl"; mk_plain "$PAR2"
mkdir -p "$T/$SID/subagents"
mk_chain "$T/$SID/subagents/agent-cafe.jsonl"
call "$SID" "$PAR2" cafe >/dev/null
if noticed "$SID" cafe; then
    echo "probe_D449: контроль — цепочка самого субагента не зачтена, судить нечем" >&2
    exit 2
fi
exit 0
